*{box-sizing:border-box}html,body{margin:0;height:100%;background:var(--cream);color:var(--ink);font-family:Arial,sans-serif}.top{height:64px;background:var(--paper);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 18px;position:relative;z-index:20}.brand{font-weight:800;letter-spacing:.08em}.tools{display:flex;gap:8px;flex-wrap:wrap}.btnx{border:1px solid #cfc8bb;background:#fff;padding:9px 13px;font-weight:700}.btnx.primary{background:var(--green);color:#fff;border-color:var(--green)}.workspace{height:calc(100vh - 64px);display:grid;grid-template-columns:310px 1fr 330px;min-height:600px}.side{background:var(--paper);overflow:auto;padding:18px;border-right:1px solid var(--line);z-index:5}.right{border-right:0;border-left:1px solid var(--line)}.map{position:relative;min-width:0}.mapbox{position:absolute;inset:0}.panel{border:1px solid var(--line);background:#fff;padding:15px;margin-bottom:14px}.panel h6{font-weight:800;text-transform:uppercase;letter-spacing:.08em;font-size:11px;color:var(--green)}.metric{font-size:25px;font-weight:800}.muted{font-size:12px;color:var(--muted);line-height:1.6}.status{padding:10px;background:#edf1eb;font-size:12px}.coord{font-family:monospace;font-size:12px;word-break:break-all}.legend{display:flex;gap:8px;align-items:center;font-size:12px;margin:7px 0}.dot{width:12px;height:12px;background:var(--green);display:inline-block}.dot.blue{background:#3478b8}.dot.gold{background:#b78b3c}.map-hint{position:absolute;left:18px;top:18px;background:rgba(255,253,249,.94);padding:12px 15px;box-shadow:0 5px 25px #0002;z-index:4;max-width:360px;font-size:12px}.mode{font-size:12px;font-weight:800}.table-mini{width:100%;font-size:11px}.table-mini td{padding:4px;border-bottom:1px solid #eee}.canvas2d{width:100%;height:260px;border:1px solid var(--line);background:#faf9f5}.feature-card{padding:11px;border:1px solid var(--line);margin-bottom:8px}.feature-card strong{display:block}.badge-soft{background:#edf1eb;padding:4px 7px;font-size:10px;font-weight:700}.webgpu{font-size:11px}.footer-note{font-size:10px;color:#7b8278;margin-top:12px}
@media(max-width:1050px){.workspace{grid-template-columns:260px 1fr}.right{display:none}}@media(max-width:700px){.top{height:auto;min-height:64px;align-items:flex-start;padding:12px;gap:10px;flex-direction:column}.workspace{height:calc(100vh - 110px);grid-template-columns:1fr}.side{display:none}.map-hint{max-width:280px}}
